package com.nigson.commerce.fulfillment;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.commerce.platform.AuditWriter;
import com.nigson.commerce.inventory.InventoryAuthority;
import com.nigson.shared.security.ActorAssertion;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Durable source acknowledgement intent only; never integration SQL or carrier HTTP. */
public final class CarrierReconciliationCommands {
 public record Intent(UUID command,long generation,CarrierReconciliationValues.Request request,CarrierReconciliationValues.Result completed,ProblemCode rejected){@Override public String toString(){return "CarrierReconciliationIntent[protected]";}}
 private static final String OP="API-191-PRIVATE-ACK";private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final InventoryAuthority authority;private final AuditWriter audit;private final Clock clock;
 public CarrierReconciliationCommands(JdbcTemplate jdbc,PlatformTransactionManager manager,InventoryAuthority authority,AuditWriter audit,Clock clock){this.jdbc=jdbc;this.authority=authority;this.audit=audit;this.clock=clock;tx=new TransactionTemplate(manager);tx.setTimeout(3);}
 public void authority(ActorAssertion.Actor actor){authority.require(actor);ActorAssertion.recentMfa(actor,clock);}
 private java.sql.Timestamp stamp(Instant at){return java.sql.Timestamp.from(at);}
 private void limits(){jdbc.execute("SET LOCAL lock_timeout='350ms'");jdbc.execute("SET LOCAL statement_timeout='800ms'");}
 private CarrierReconciliationValues.Request snapshot(UUID shipment,Long expected,String reason){var rows=jdbc.queryForList("SELECT s.version,s.status,s.provider,s.booking_request_id,s.package_snapshot::text,m.code,m.currency_code,o.currency_code AS order_currency,o.carrier_snapshot::text AS carrier FROM commerce.shipment s JOIN commerce.sales_order o ON o.id=s.order_id JOIN commerce.market m ON m.id=o.market_id WHERE s.id=? FOR SHARE OF s,o",shipment);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();if(expected!=null&&((Number)row.get("version")).longValue()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!"FEDEX".equals(row.get("provider"))||row.get("booking_request_id")==null||!"NG".equals(row.get("code"))||!"NGN".equals(row.get("currency_code"))||!"NGN".equals(row.get("order_currency")))throw FulfillmentValues.rule();if("CANCELLED".equals(row.get("status")))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);var snapshot=EventCodec.JSON.readTree(row.get("package_snapshot").toString());var carrier=EventCodec.JSON.readTree(row.get("carrier").toString());UUID reference=(UUID)row.get("booking_request_id");String mode=snapshot.path("mode").asString();if(!"FEDEX".equals(carrier.path("provider").asString())||!"NGN".equals(carrier.path("currency").asString())||!reference.toString().equals(snapshot.path("bookingReference").asString())||!mode.equals(carrier.path("mode").asString()))throw FulfillmentValues.rule();return new CarrierReconciliationValues.Request(reference,mode,reason);}
 public Intent claim(ActorAssertion.Actor actor,UUID shipment,long expected,String reason,String key,UUID correlation){authority(actor);ApiValues.idempotencyKey(key);for(UUID id:Arrays.asList(shipment,correlation))ApiValues.uuid(id==null?null:id.toString());if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();CarrierReconciliationValues.requireReason(reason);String principal=actor.party().toString();String hash=EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("shipment",shipment,"version",expected,"reason",reason)));UUID candidate=EventCodec.uuid7(clock.instant());
  try{return tx.execute(status->{limits();authority.stabilize(actor);authority(actor);jdbc.update("INSERT INTO commerce.idempotency_record(id,created_by,updated_by,principal_key,operation,request_key,request_hash,state,resource_id,lease_until,expires_at,response_body) VALUES (?,?,?,?,?,?,?,'RUNNING',?,NULL,?,'{}'::jsonb) ON CONFLICT(principal_key,operation,request_key) DO NOTHING",candidate,principal,principal,principal,OP,key,hash,shipment,stamp(clock.instant().plusSeconds(86400)));var row=jdbc.queryForMap("SELECT * FROM commerce.idempotency_record WHERE principal_key=? AND operation=? AND request_key=? FOR UPDATE",principal,OP,key);if(!hash.equals(row.get("request_hash")))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);UUID command=(UUID)row.get("id");long generation=((Number)row.get("version")).longValue();var saved=EventCodec.JSON.readTree(row.get("response_body").toString());if("SUCCEEDED".equals(row.get("state"))){if(saved.has("error"))return new Intent(command,generation,null,null,ProblemCode.valueOf(saved.path("error").asString()));return new Intent(command,generation,null,CarrierReconciliationValues.result(saved.path("result"),shipment),null);}var lease=(java.sql.Timestamp)row.get("lease_until");if(lease!=null&&lease.toInstant().isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);CarrierReconciliationValues.Request request=saved.has("request")?EventCodec.JSON.treeToValue(saved.path("request"),CarrierReconciliationValues.Request.class):snapshot(shipment,expected,reason);if(saved.has("request")&&!request.equals(snapshot(shipment,null,reason)))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);var body=EventCodec.JSON.createObjectNode().put("outcome","CALLING");body.set("request",EventCodec.JSON.valueToTree(request));jdbc.update("UPDATE commerce.idempotency_record SET response_body=?::jsonb,lease_until=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",EventCodec.JSON.writeValueAsString(body),stamp(clock.instant().plusSeconds(30)),stamp(clock.instant()),principal,command);audit.append(principal,AuditValues.ActorKind.USER,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.SHIPMENT,shipment,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("version",expected),null);return new Intent(command,generation+1,request,null,null);});}catch(org.springframework.dao.DataAccessException busy){for(Throwable t=busy;t!=null;t=t.getCause())if(t instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw busy;}
 }
 public void unknown(Intent intent,ActorAssertion.Actor actor,UUID shipment,UUID correlation){tx.executeWithoutResult(status->{limits();var body=EventCodec.JSON.createObjectNode().put("outcome","UNKNOWN");body.set("request",EventCodec.JSON.valueToTree(intent.request()));int changed=jdbc.update("UPDATE commerce.idempotency_record SET response_body=?::jsonb,lease_until=NULL,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=? AND state='RUNNING'",EventCodec.JSON.writeValueAsString(body),stamp(clock.instant()),actor.party().toString(),intent.command(),intent.generation());if(changed==1)audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.SHIPMENT,shipment,correlation,AuditValues.Reason.RECONCILIATION,null,Map.of("state","UNKNOWN"),null);});}
 public void finish(Intent intent,ActorAssertion.Actor actor,UUID shipment,UUID correlation,CarrierReconciliationValues.Result result,ProblemCode rejected){tx.executeWithoutResult(status->{limits();var body=EventCodec.JSON.createObjectNode();if(rejected!=null)body.put("error",rejected.name());else body.set("result",EventCodec.JSON.valueToTree(result));int changed=jdbc.update("UPDATE commerce.idempotency_record SET state='SUCCEEDED',response_status=?,response_body=?::jsonb,lease_until=NULL,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=? AND state='RUNNING'",rejected==null?202:rejected.status,EventCodec.JSON.writeValueAsString(body),stamp(clock.instant()),actor.party().toString(),intent.command(),intent.generation());if(changed!=1)throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.SHIPMENT,shipment,correlation,AuditValues.Reason.RECONCILIATION,null,Map.of("state",result==null?"FAILED":"SUCCEEDED"),null);});}
}
